PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT (?a_wr AS ?wr) (?emotionCount AS ?count)
WHERE {
  { SELECT ?a_wr (COUNT(DISTINCT ?e_emotion) AS ?emotionCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
        ?a_lemma a ?a_lemmaType .
        ?a_lemma ontolex:writtenRep ?a_wr .
      }
      ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
      ?e_elitaLemma elita:HasEmotion ?e_emotion .
      ?e_emotion rdfs:label ?e_emotionLabel .
    }
    GROUP BY ?a_wr
    HAVING (COUNT(DISTINCT ?e_emotion) > 6)
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?a_wr AS ?wr) (?e_emotionLabel AS ?emotionLabel)
WHERE {
  { SELECT (MAX(xsd:float(?x_polarityValue)) AS ?r_value) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?w_lemmaType { lila:Lemma lila:Hypolemma }
        ?w_lemma a ?w_lemmaType .
        ?w_lemma ontolex:writtenRep ?w_wr .
        FILTER(STR(?w_wr) = "appartenenza") .
      }
      ?x_sentixLemma ontolex:canonicalForm ?w_lemma ;
                   marl:hasPolarity ?x_polarity ;
                   marl:hasPolarityValue ?x_polarityValue .
      BIND(STRAFTER(STR(?x_polarity), "#") AS ?x_polarityLabel)
    }
  }
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma lila:hasPOS lila:noun .
    ?a_lemma ontolex:writtenRep ?a_wr .
  }
  ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
  ?e_elitaLemma elita:HasEmotion ?e_emotion .
  VALUES ?e_emotion { elita:Fiducia }
  ?e_emotion rdfs:label ?e_emotionLabel .
  ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
               marl:hasPolarity ?s_polarity ;
               marl:hasPolarityValue ?s_polarityValue .
  BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
  FILTER(xsd:float(?s_polarityValue) > xsd:float(?r_value))
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?a_lemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma ontolex:writtenRep ?a_wr .
  }
  {
    ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
    ?e_elitaLemma elita:HasEmotion ?e_emotion .
    VALUES ?e_emotion { elita:Disgusto }
    ?e_emotion rdfs:label ?e_emotionLabel .
  }
  UNION
  {
    ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
                 marl:hasPolarity ?s_polarity ;
                 marl:hasPolarityValue ?s_polarityValue .
    BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
    FILTER(xsd:float(?s_polarityValue) < -0.9)
  }
}

