PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT (?b_wordRel AS ?wordRel) (?b_itLemmaString AS ?itLemmaString)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?a_seedWord a ontolex:Word ;
              lexinfo:partOfSpeech [ rdfs:label ?a_posLabel ] ;
              ontolex:canonicalForm [ ontolex:writtenRep ?a_seedForm ] ;
              ontolex:sense ?a_seedSense .
    FILTER(str(?a_seedForm) = "autoveicolo") .
    ?a_senseRel lexinfo:partMeronym ?a_seedSense .
    OPTIONAL { ?a_senseRel skos:definition ?a_definition . }
    ?a_wordRel ontolex:sense ?a_senseRel ;
             ontolex:canonicalForm ?a_formRel .
    ?a_formRel ontolex:writtenRep ?a_itLemmaString .
    ?a_wordRel a ontolex:Word ;
              lexinfo:partOfSpeech [ rdfs:label ?b_posLabel ] ;
              ontolex:canonicalForm [ ontolex:writtenRep ?b_seedForm ] ;
              ontolex:sense ?a_senseRel .
    ?b_senseRel lexinfo:partMeronym ?a_senseRel .
    OPTIONAL { ?b_senseRel skos:definition ?b_definition . }
    ?b_wordRel ontolex:sense ?b_senseRel ;
             ontolex:canonicalForm ?b_formRel .
    ?b_formRel ontolex:writtenRep ?b_itLemmaString .
  }
}

