    ?a_wordRel ontolex:sense ?a_senseRel ;
             ontolex:canonicalForm ?a_formRel .
    ?a_formRel ontolex:writtenRep ?a_itLemmaString .
  }
  ?a_wordRel ontolex:canonicalForm ?j_liitaLemma .
  GRAPH <http://liita.it/data> { ?j_liitaLemma a ?j_liitaLemmaType ; ontolex:writtenRep ?j_liitaWR . FILTER(?j_liitaLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  FILTER NOT EXISTS {
    ?t_itToSicEntry ontolex:canonicalForm ?j_liitaLemma ;
                 vartrans:translatableAs ?t_sicEntry .
    ?t_sicEntry ontolex:canonicalForm ?t_sicLemma .
