WHERE {
  { SELECT ?e_emotionLabel (COUNT(DISTINCT ?v_lemma) AS ?emotionCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?v_lemmaType { lila:Lemma lila:Hypolemma }
