  { SELECT (COUNT(DISTINCT ?v2_lemma) AS ?sadnessCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?v2_lemmaType { lila:Lemma lila:Hypolemma }
        ?v2_lemma a ?v2_lemmaType .
        ?v2_lemma lila:hasPOS lila:verb .
