PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?a_itLemmaString AS ?itLemmaString) ?definition ?emotionCount ?maxPolarity ?sicWR ?parWR
WHERE {
  { SELECT ?a_word ?a_itLemmaString (MIN(xsd:float(?a_definition)) AS ?definition) WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?a_word a ontolex:Word ;
              lexinfo:partOfSpeech [ rdfs:label ?a_posLabel ] ;
              ontolex:sense ?a_sense ;
              ontolex:canonicalForm ?a_form .
        ?a_form ontolex:writtenRep ?a_itLemmaString .
        OPTIONAL { ?a_sense skos:definition ?a_definition . }
        FILTER(CONTAINS(LCASE(STR(?a_definition)), LCASE("dolore"))) .
      }
    }
    GROUP BY ?a_word ?a_itLemmaString
  }
  ?a_word ontolex:canonicalForm ?j_liitaLemma .
  GRAPH <http://liita.it/data> { ?j_liitaLemma a ?j_liitaLemmaType ; ontolex:writtenRep ?j_liitaWR . FILTER(?j_liitaLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  { SELECT ?j_liitaLemma (COUNT(DISTINCT ?e_emotion) AS ?emotionCount) WHERE {
      ?e_elitaLemma ontolex:canonicalForm ?j_liitaLemma .
      ?e_elitaLemma elita:HasEmotion ?e_emotion .
      ?e_emotion rdfs:label ?e_emotionLabel .
    }
    GROUP BY ?j_liitaLemma
  }
  { SELECT ?j_liitaLemma (MAX(xsd:float(?s_polarityValue)) AS ?maxPolarity) WHERE {
      ?s_sentixLemma ontolex:canonicalForm ?j_liitaLemma ;
                   marl:hasPolarity ?s_polarity ;
                   marl:hasPolarityValue ?s_polarityValue .
      BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
    }
    GROUP BY ?j_liitaLemma
  }
  { SELECT ?j_liitaLemma (MIN(xsd:float(?ts_sicWR)) AS ?sicWR) WHERE {
      ?ts_itToSicEntry ontolex:canonicalForm ?j_liitaLemma ;
                   vartrans:translatableAs ?ts_sicEntry .
      ?ts_sicEntry ontolex:canonicalForm ?ts_sicLemma .
      ?ts_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
               ontolex:writtenRep ?ts_sicWR .
    }
    GROUP BY ?j_liitaLemma
  }
  { SELECT ?j_liitaLemma (MIN(xsd:float(?tp_parWR)) AS ?parWR) WHERE {
      ?tp_itToParEntry ontolex:canonicalForm ?j_liitaLemma ;
                   vartrans:translatableAs ?tp_parEntry .
      ?tp_parEntry ontolex:canonicalForm ?tp_parLemma .
      ?tp_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
               ontolex:writtenRep ?tp_parWR .
    }
    GROUP BY ?j_liitaLemma
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?e_emotionLabel AS ?emotionLabel) ?posCount ?negCount
WHERE {
  { SELECT ?e_emotionLabel (COUNT(DISTINCT ?a_wr) AS ?posCount) WHERE {
      { SELECT ?e_emotionLabel ?a_wr (AVG(xsd:float(?s_polarityValue)) AS ?avgPol) WHERE {
          GRAPH <http://liita.it/data> {
            VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
            ?a_lemma a ?a_lemmaType .
            ?a_lemma ontolex:writtenRep ?a_wr .
          }
          ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
          ?e_elitaLemma elita:HasEmotion ?e_emotion .
          ?e_emotion rdfs:label ?e_emotionLabel .
          ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
                       marl:hasPolarity ?s_polarity ;
                       marl:hasPolarityValue ?s_polarityValue .
          BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
        }
        GROUP BY ?e_emotionLabel ?a_wr
      }
      FILTER(xsd:float(?avgPol) > 0)
    }
    GROUP BY ?e_emotionLabel
  }
  { SELECT ?e_emotionLabel (COUNT(DISTINCT ?a2_wr) AS ?negCount) WHERE {
      { SELECT ?e_emotionLabel ?a2_wr (AVG(xsd:float(?s2_polarityValue)) AS ?avgPol) WHERE {
          GRAPH <http://liita.it/data> {
            VALUES ?a2_lemmaType { lila:Lemma lila:Hypolemma }
            ?a2_lemma a ?a2_lemmaType .
            ?a2_lemma ontolex:writtenRep ?a2_wr .
          }
          ?e2_elitaLemma ontolex:canonicalForm ?a2_lemma .
          ?e2_elitaLemma elita:HasEmotion ?e2_emotion .
          ?e2_emotion rdfs:label ?e_emotionLabel .
          ?s2_sentixLemma ontolex:canonicalForm ?a2_lemma ;
                       marl:hasPolarity ?s2_polarity ;
                       marl:hasPolarityValue ?s2_polarityValue .
          BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s2_polarityLabel)
        }
        GROUP BY ?e_emotionLabel ?a2_wr
      }
      FILTER(xsd:float(?avgPol) < 0)
    }
    GROUP BY ?e_emotionLabel
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?a_wr AS ?wr)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma ontolex:writtenRep ?a_wr .
  }
  ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
  ?e_elitaLemma elita:HasEmotion ?e_emotion .
  VALUES ?e_emotion { elita:Tristezza }
  ?e_emotion rdfs:label ?e_emotionLabel .
  ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
               marl:hasPolarity ?s_polarity ;
               marl:hasPolarityValue ?s_polarityValue .
  BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
  FILTER NOT EXISTS {
    ?s2_sentixLemma ontolex:canonicalForm ?a_lemma ;
                 marl:hasPolarity ?s2_polarity ;
                 marl:hasPolarityValue ?s2_polarityValue .
    BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s2_polarityLabel)
    FILTER(xsd:float(?s2_polarityValue) <= 0)
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?sentimentNoEmotion ?emotionNoSentiment
WHERE {
  { SELECT (COUNT(DISTINCT ?a_lemma) AS ?sentimentNoEmotion) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
        ?a_lemma a ?a_lemmaType .
        ?a_lemma ontolex:writtenRep ?a_wr .
      }
      ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
                   marl:hasPolarity ?s_polarity ;
                   marl:hasPolarityValue ?s_polarityValue .
      BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
      FILTER NOT EXISTS {
        ?e1_elitaLemma ontolex:canonicalForm ?a_lemma .
        ?e1_elitaLemma elita:HasEmotion ?e1_emotion .
        ?e1_emotion rdfs:label ?e1_emotionLabel .
      }
    }
  }
  { SELECT (COUNT(DISTINCT ?b_lemma) AS ?emotionNoSentiment) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?b_lemmaType { lila:Lemma lila:Hypolemma }
        ?b_lemma a ?b_lemmaType .
        ?b_lemma ontolex:writtenRep ?b_wr .
      }
      ?e2_elitaLemma ontolex:canonicalForm ?b_lemma .
      ?e2_elitaLemma elita:HasEmotion ?e2_emotion .
      ?e2_emotion rdfs:label ?e2_emotionLabel .
      FILTER NOT EXISTS {
        ?s2_sentixLemma ontolex:canonicalForm ?b_lemma ;
                     marl:hasPolarity ?s2_polarity ;
                     marl:hasPolarityValue ?s2_polarityValue .
        BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s2_polarityLabel)
      }
    }
  }
}
